Translate("esES", "apothecary-lydon", {
	title = "Boticario Lydon",
	subtitle = "Boticario de Molino Tarren",
	found = "Molino Tarren",
	hint = "Busque al sombrío boticario de la Sociedad en Molino Tarren.",
	allegiance = "Real Sociedad de Boticarios · Renegados",
	aliases = { "Lydon" },
	sections = {
