			text = [=[El boticario Lydon es el hombre de la {link:royal-apothecary-society}Real Sociedad de Boticarios{/link} en {link:tarren-mill}Molino Tarren{/link}. Es un alma sombría para quien cada día de no-muerte es una desdicha. Solo una cosa le levanta el ánimo: el sufrimiento de los vivos. Su trabajo es preparar la nueva peste de {link:sylvanas-windrunner}la Dama Oscura{/link} para {link:hillsbrad-foothills}Trabalomas{/link}, y lo hace con esmero y una alegría terrible.]=],
		},
		{
			title = "Importancia",
			text = [=[El {link:master-apothecary-faranell}maestro boticario Faranell{/link} dice que Lydon es uno de los miembros más entregados y hábiles de la Sociedad. En sus elixires, la peste destinada a la {link:scourge}Plaga{/link} se vuelve por primera vez contra los humanos.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Prepara tres elixires, de sufrimiento, de dolor y de agonía, cada uno más mortífero que el anterior.
• Los prueba en su rana, Umpi, en el perro del granjero {link:farmer-ray}Ray{/link} y en granjeros capturados.
• Prepara una toxina para el {link:apothecary-zamah}boticario Zamah{/link} contra la {link:venture-company}Ventura y Cía.{/link} en Stonetalon, con la sangre de inocentes arrebatada a magos del {link:syndicate}Sindicato{/link}.
• Estudia el veneno del dios araña de los trols Witherbark, y se lo envía a {link:master-apothecary-faranell}Faranell{/link}.
• En los días aburridos abre su tarro de formaldehído para disfrutar de su aroma, lo que pone nervioso a Umpi.]=],
		},
	},
	chapters = {
		{
			title = "El elixir de dolor",
			hint = "Pruebe el elixir del boticario en un perro de granja.",
			text = [=[Lydon quería una prueba. Envió su elixir a la granja del norte de los {link:hillsbrad-fields}Campos de Trabalomas{/link}, para dárselo como golosina al perrito del granjero {link:farmer-ray}Ray{/link}, Stanley. Aquello en lo que se convirtió el perro después, su amo tuvo que matarlo con sus propias manos.]=],
		},
		{
			title = "El elixir de agonía",
			hint = [=[Lleve el brebaje apestado del boticario a los granjeros capturados.]=],
			text = [=[El último elixir necesitaba las flores hediondas de la {link:nethander-stead}Granja Nethander{/link}, un coloide preparado por el propio {link:master-apothecary-faranell}Faranell{/link} y un barril de cerveza negra enana de {link:dun-garok}Dun Garok{/link}. Luego Lydon hizo dejar el barril contaminado en la sala donde los {link:forsaken}Renegados{/link} tenían a sus granjeros capturados. Lo llamó darles una fiesta.]=],
		},
	},
	mentions = {
		{
			text = [=[Viaje a las {link:hillsbrad-foothills}Laderas de Trabalomas{/link}, de parte del boticario {link:apothecary-renferrel}Renferrel{/link}]=],
		},
		{ text = "Elixir de sufrimiento" },
		{ text = "Elixir de dolor" },
		{ text = "Elixir de agonía" },
		{ text = "Elixir de agonía" },
		{ text = "Viaje a {link:tarren-mill}Molino Tarren{/link}" },
		{ text = "Sangre de inocentes" },
		{ text = "Veneno para {link:undercity}Entrañas{/link}" },
	},
	bonds = {
		{ id = "master-apothecary-faranell", name = "Maestro boticario Faranell", note = "su superior" },
		{ id = "apothecary-renferrel", name = "Boticario Renferrel", note = "comparte sus hallazgos" },
		{ id = "apothecary-zamah", name = "Boticario Zamah", note = "le pidió una toxina" },
		{ id = "stanley", name = "Stanley", note = "su sujeto de pruebas" },
		{ id = "serge-hinott", name = "Serge Hinott", note = "trabaja a su lado" },
	},
})

