Translate("esES", "farmer-getz", {
	title = "Granjero Getz",
	subtitle = "Terrateniente de Trabalomas",
	found = "Las granjas del norte de los Campos de Trabalomas",
	hint = "Visite las granjas del norte de los Campos de Trabalomas.",
	allegiance = "Trabalomas",
	aliases = { "Getz" },
	sections = {
		{
			title = "Resumen",
			text = [=[Getz es dueño de una de las granjas del norte de los {link:hillsbrad-fields}Campos de Trabalomas{/link}, junto a la tierra del granjero {link:farmer-ray}Ray{/link}. Sus peones trabajan los campos a la intemperie, sin muros que los protejan. Los {link:forsaken}Renegados{/link} lo han señalado para morir. Para ellos, un granjero que alimenta a {link:hillsbrad-foothills}Trabalomas{/link} es un soldado de su ejército.]=],
		},
		{
			title = "Importancia",
			text = [=[Getz y {link:farmer-ray}Ray{/link} representan a todos los granjeros de {link:hillsbrad-foothills}Trabalomas{/link}. Sus campos son el alimento del pueblo, y por eso son los primeros en pagar por la guerra.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Comparte con el granjero {link:farmer-ray}Ray{/link} un lugar en la primera lista de muertos de la alta ejecutora.]=],
		},
		{
			title = "Sin registro",
			text = [=[Poco se ha escrito de Getz más allá de su tierra y del peligro que corre. Ningún registro menciona su familia ni su historia.]=],
		},
	},
	mentions = {
		{ text = "{link:battle-of-hillsbrad}La batalla de Trabalomas{/link}" },
	},
	bonds = {
		{ id = "farmer-ray", name = "Granjero Ray", note = "su vecino" },
	},
})

Translate("esES", "stanley", {
	title = "Stanley",
	subtitle = "El perro del granjero Ray",
	found = "La granja del granjero Ray en los Campos de Trabalomas",
	hint = [=[Busque al perrito en la granja del norte de los Campos de Trabalomas.]=],
	allegiance = "Granjero Ray",
	sections = {
		{
			title = "Resumen",
			text = [=[Stanley era el perrito del granjero {link:farmer-ray}Ray{/link}. Un boticario Renegado lo eligió para probar un nuevo elixir, preparado con sangre de pumas. Después de tomarlo, creció hasta un tamaño monstruoso y atacaba con saña a cualquiera que se le acercara. Ray tuvo que sacrificarlo.]=],
		},
		{
			title = "Importancia",
			text = [=[Stanley fue el primer ser vivo de {link:hillsbrad-foothills}Trabalomas{/link} que mostró lo que estaba preparando la {link:royal-apothecary-society}Real Sociedad de Boticarios{/link}. Su destino puso a {link:phin-odelic}Phin Odelic{/link} tras la pista de una nueva peste.]=],
		},
		{
			title = "Hazañas",
			text = [=[• Tomó el elixir de dolor de la mano de un desconocido.
• Se volvió tan grande y feroz que su propio amo tuvo que matarlo. {link:phin-odelic}Phin Odelic{/link} cuenta su historia en {link:southshore}Costasur{/link}.]=],
		},
	},
	mentions = {
		{ text = "Elixir de dolor" },
		{ text = "¿Indicios de una nueva peste?" },
	},
	bonds = {
		{ id = "farmer-ray", name = "Granjero Ray", note = "su amo" },
		{ id = "apothecary-lydon", name = "Boticario Lydon", note = "lo envenenó" },
		{ id = "phin-odelic", name = "Phin Odelic", note = "busca la causa de su locura" },
	},
})

Translate("esES", "magistrate-burnside", {
