	},
	bonds = {
		{ id = "high-executor-darthalia", name = "Alta ejecutora Darthalia", note = "ha ordenado su muerte" },
	},
})

Translate("esES", "captain-ironhill", {
	title = "Capitán Ironhill",
	subtitle = "Comandante de Dun Garok",
	found = "Dun Garok",
	hint = "Busque al capitán enano que manda en Dun Garok.",
	allegiance = "Reino de Forjaz · Alianza",
	aliases = { "Ironhill" },
	sections = {
		{
			title = "Resumen",
			text = [=[El capitán Ironhill manda la fortaleza enana de {link:dun-garok}Dun Garok{/link}. Sus montañeros, fusileros y sacerdotes guardan el sudeste de {link:hillsbrad-foothills}Trabalomas{/link} y a los humanos que viven allí. Los {link:forsaken}Renegados{/link} llaman a sus enanos rompetobillos. También saben exactamente dónde está su fortaleza, y pretenden tomarla.]=],
		},
		{
			title = "Importancia",
			text = [=[{link:dun-garok}Dun Garok{/link} es la prueba de que el {link:kingdom-of-ironforge}Reino de Forjaz{/link} no ha olvidado sus juramentos a los humanos del norte. Ironhill resiste frente a los muertos con una pequeña guarnición y una cerveza negra fuerte.]=],
		},
		{
