			text = [=[• Dirige la guarnición de {link:dun-garok}Dun Garok{/link}.
• Sus exploradores se llevaron el equipo de un espía Renegado que dejó su campamento sin vigilancia.]=],
		},
	},
	mentions = {
		{ text = "{link:battle-of-hillsbrad}La batalla de Trabalomas{/link}" },
