})

Translate("esES", "battle-of-hillsbrad", {
	title = "La batalla de Trabalomas",
	sections = {
		{
			title = "Resumen",
			text = [=[La batalla de Trabalomas es la guerra que los {link:forsaken}Renegados{/link} de {link:tarren-mill}Molino Tarren{/link} libran ahora contra los humanos de las laderas. Su objetivo es claro: quebrar a los humanos de {link:hillsbrad-foothills}Trabalomas{/link} hasta que los boticarios terminen la nueva peste, y después arrasar {link:southshore}Costasur{/link}.]=],
		},
		{
			title = "La campaña",
			text = [=[La orden llegó de {link:varimathras}Varimathras{/link} a la alta ejecutora {link:high-executor-darthalia}Darthalia{/link}. Cuando su exploradora de la {link:southpoint-tower}Torre Austral{/link} avisó de que el pueblo estaba maduro, el ataque comenzó por etapas.

• {b}Las granjas.{/b} Los guardias de la muerte atacaron primero las granjas del norte y a sus dueños, para cortar el alimento de {link:hillsbrad-foothills}Trabalomas{/link}.
• {b}Los huertos.{/b} Los campesinos que huyeron a los huertos del sur fueron perseguidos allí.
• {b}La herrería.{/b} El herrero y sus aprendices fueron asesinados, y el hierro del pueblo fue robado.
• {b}El consejo.{/b} El magistrado y el consejo fueron señalados para morir, la carta del pueblo para ser quemada y su registro para ser robado.
• {b}La mina.{/b} El capataz y los mineros de la {link:azurelode-mine}Mina Azur{/link} fueron atacados, para que {link:sylvanas-windrunner}la Dama Oscura{/link} pudiera armar a sus soldados con su hierro.
• {b}{link:dun-garok}Dun Garok{/link}.{/b} Por último llegó el asedio de la fortaleza enana en la {link:thoradin-s-wall}Muralla de Thoradin{/link}.]=],
		},
		{
			title = "El otro bando",
			text = [=[Los humanos no mueren en silencio. Vecinos de {link:hillsbrad-foothills}Trabalomas{/link} han matado a guardias, boticarios y mortacechadores {link:forsaken}Renegados{/link}, y han emboscado los suministros enviados desde {link:undercity}Entrañas{/link}. {link:high-executor-darthalia}Darthalia{/link} guarda sus nombres en una lista de recompensas.]=],
		},
		{
			title = "Los boticarios",
			text = [=[Mientras los soldados luchan, el boticario {link:apothecary-lydon}Lydon{/link} prueba sus elixires en los perros y en los granjeros capturados de {link:hillsbrad-foothills}Trabalomas{/link}. Cada uno pretende ser un paso hacia la peste que ha ordenado {link:sylvanas-windrunner}la Dama Oscura{/link}.]=],
		},
	},
})

Translate("esES", "internment-camps", {
	title = "Campos de internamiento",
	aliases = { "campo de internamiento" },
	sections = {
		{
			title = "Resumen",
			text = [=[Tras la {link:second-war}Segunda Guerra{/link}, los orcos que sobrevivieron no fueron pasados a cuchillo. Se los reunió en campos de internamiento por todo {link:lordaeron}Lordaeron{/link}, custodiados por los soldados de la {link:alliance}Alianza{/link}. Los campos debían servir para retener a un enemigo vencido. Se convirtieron en algo peor.]=],
		},
		{
			title = "El letargo",
			text = [=[Separados del poder demoníaco que los había impulsado, los orcos de los campos se volvieron apáticos y enfermos de espíritu. Muchos simplemente se sentaban tras los muros y no intentaban marcharse. Los humanos que los custodiaban no podían entenderlo. Algunos se compadecían de ellos. Otros se lucraban con ellos.]=],
		},
		{
			title = "Durnholde",
			text = [=[Los campos se gobernaban desde el {link:durnholde-keep}Castillo de Durnholde{/link}, en {link:hillsbrad-foothills}Trabalomas{/link}, bajo el teniente general {link:aedelas-blackmoore}Aedelas Blackmoore{/link}. Blackmoore veía más que prisioneros tras sus muros. Veía un ejército que podía ser suyo, si lo dirigía un {link:orcs}orco{/link} criado por él mismo.]=],
		},
		{
			title = "La liberación",
			text = [=[Ese {link:orcs}orco{/link} era {link:thrall}Thrall{/link}. Escapó de {link:durnholde-keep}Durnholde{/link}, encontró a los clanes libres y aprendió las costumbres de los chamanes. Con {link:orgrim-doomhammer}Orgrim Doomhammer{/link} a su lado, atacó los campos uno por uno y liberó a los orcos que había dentro. Doomhammer cayó en una de esas batallas. Por fin Thrall llegó a la propia Durnholde, y los campos llegaron a su fin.]=],
		},
	},
})
